    pub struct CGI {
        pub plmn_identity: PLMNidentity,
        pub lac: LAC,
        pub ci: CI,
        pub rac: Option<RAC>,
        pub ie_extensions: Option<ProtocolExtensionContainer<'static>>,
    }
    impl CGI {
        pub fn new(
            plmn_identity: PLMNidentity,
            lac: LAC,
            ci: CI,
            rac: Option<RAC>,
            ie_extensions: Option<ProtocolExtensionContainer<'static>>,
        ) -> Self {
            Self {
                plmn_identity,
                lac,
                ci,
                rac,
                ie_extensions,
            }
        }
    }
